void tempo_properties_tests(const std::filesystem::path& dir){
    SegmentDocument d;require(d.add_tempo(768,137.25)&&d.add_tempo(3072,180),"Tempo properties fixture");
    auto tree=Chunk::parse(d.save_bytes());Chunk opaque;opaque.id="zzzz";opaque.data={0x71,0x92,0x13};opaque.padding=0xb4;tree.children.push_back(opaque);
    d.load(tree.encode());const auto before=d.save_bytes();d.select(1);
    const auto second=d.tempos()[2];const auto at=d.timeline().clocks({1,1,24});
    require(at==3864&&d.move_selected_tempo(at),"Property position uses musical clocks");
    const auto moved=d.save_bytes();require(d.tempos()[2].time==3864&&d.tempos()[2].bpm==137.25&&d.tempos()[2].selected,"Moved marker retains Tempo and selection after sorting");
    require(d.tempos()[1].time==second.time&&d.tempos()[1].bpm==second.bpm,"Position edit leaves unselected marker untouched");
    require(Chunk::parse(moved).find("zzzz")->encode()==opaque.encode(),"Position edit retains unknown chunk and padding");
    require(d.undo()&&d.save_bytes()==before&&d.redo()&&d.save_bytes()==moved,"Position edit is one whole-document UndoRedo");
    d.select(2);const bool undo=d.can_undo(),redo=d.can_redo();
    require(!d.move_selected_tempo(-1)&&!d.move_selected_tempo(d.length())&&!d.move_selected_tempo(3864)&&d.save_bytes()==moved&&d.can_undo()==undo&&d.can_redo()==redo,"Rejected or unchanged position retains bytes and history");
    require(!d.change_selected(0.99)&&!d.change_selected(1000.01)&&!d.change_selected(std::numeric_limits<double>::quiet_NaN())&&d.save_bytes()==moved,"Tempo property range rejection retains bytes");
    require(d.change_selected(999.99)&&d.tempos()[2].bpm==999.99,"Two-decimal Tempo value accepted above old procedure range");
    require(d.undo()&&d.save_bytes()==moved&&d.redo()&&d.tempos()[2].bpm==999.99,"Tempo value retains independent history");
    d.select(std::vector<size_t>{1,2});require(d.move_selected_tempo(3864),"Original SetData permits equal-time move of first selection");
    require(d.tempos()[1].bpm==999.99&&d.tempos()[2].bpm==180&&d.tempos()[1].selected&&d.tempos()[2].selected,"Equal-time insertion follows existing node and preserves peer selection");
    const auto duplicate=d.save_bytes();SegmentDocument reread;reread.load(duplicate);require(reread.save_bytes()==duplicate&&reread.tempos()[1].time==3864&&reread.tempos()[2].time==3864,"Equal-time Tempo native save retains stable order");
    reread.select(std::vector<size_t>{});require(!reread.move_selected_tempo(0)&&reread.save_bytes()==duplicate&&!reread.dirty()&&!reread.can_undo(),"No-selection property edit leaves clean native document unchanged");
    d.load(before);require(d.set_meter(1,3,4,4),"Variable meter property fixture");d.select(1);
    require(d.move_selected_tempo(d.timeline().clocks({2,2,12}))&&d.tempos().back().time==6924,"Tempo movement uses changed meter instead of fixed 4/4");
    const auto saved=d.save_bytes();const auto file=dir/L"tempo-properties.sgp";d.save(file.wstring());Framework f;f.open_segment(file.wstring());f.save_project((dir/L"tempo-properties.dmpj").wstring());
    Framework reload;reload.open_project((dir/L"tempo-properties.dmpj").wstring());require(reload.document(0).save_bytes()==saved&&reload.document(0).tempos().back().time==6924&&!reload.dirty(),"Separate Framework native reload preserves moved marker and meter");
    auto grouped=tree;auto& tracks=grouped.find("LIST","trkl")->children;const auto peer=tracks.front();auto alternate=peer;put32(alternate.find("trkh")->data,20,8);tracks.push_back(alternate);
    d.load(grouped.encode());d.select_track_group(8);d.select(1);require(d.move_selected_tempo(1536),"Property edit follows selected group");
    const auto result=Chunk::parse(d.save_bytes());require(result.find("LIST","trkl")->children.front().encode()==peer.encode()&&d.tempos()[1].time==1536,"Other group retains complete native bytes");
    d.load(before);d.select(std::vector<size_t>{0,2});
    require(d.tempo_at(0)==120&&d.tempo_at(767)==120&&d.tempo_at(768)==137.25&&d.tempo_at(3072)==180,"Current Tempo follows effective marker at cursor boundaries");
    require(!d.tempo_at(-1)&&!d.tempo_at(d.length()),"Current Tempo rejects cursor outside Segment");
    require(d.change_current_tempo(1536,132.25)&&d.tempos().size()==3&&d.tempos()[1].time==768&&d.tempos()[1].bpm==132.25,"Current Tempo edits preceding marker without inserting at cursor");
    require(d.tempos()[0].bpm==120&&d.tempos()[2].bpm==180&&d.tempos()[0].selected&&!d.tempos()[1].selected&&d.tempos()[2].selected,"Current Tempo ignores edit selection and preserves all selection flags and peer values");
    const auto current=d.save_bytes();require(d.dirty()&&Chunk::parse(current).find("zzzz")->encode()==opaque.encode(),"Current Tempo dirty edit retains opaque bytes and padding");
    const auto currentUndo=d.can_undo(),currentRedo=d.can_redo();
    require(!d.change_current_tempo(1536,132.25)&&!d.change_current_tempo(-1,133)&&!d.change_current_tempo(d.length(),133)&&!d.change_current_tempo(0,.99)&&!d.change_current_tempo(0,1000.01)&&!d.change_current_tempo(0,std::numeric_limits<double>::quiet_NaN())&&d.save_bytes()==current&&d.can_undo()==currentUndo&&d.can_redo()==currentRedo,"Invalid and unchanged Current Tempo preserve native bytes and history");
    require(d.undo()&&d.save_bytes()==before&&!d.dirty()&&d.redo()&&d.save_bytes()==current,"Current Tempo is one whole-document UndoRedo");
    SegmentDocument currentReload;currentReload.load(current);require(currentReload.tempo_at(1536)==132.25&&currentReload.save_bytes()==current&&!currentReload.dirty()&&!currentReload.can_undo(),"Current Tempo native bytes reload clean without session history");
    d.load(before);d.select(0);require(d.delete_selected(),"Current Tempo no preceding marker fixture");const auto missing=d.save_bytes();
    require(!d.tempo_at(0)&&!d.change_current_tempo(0,133)&&d.save_bytes()==missing&&d.tempo_at(768)==137.25,"Current Tempo does not invent a marker before first event");
    auto noTempo=SegmentDocument::create_empty(SegmentCreationLength{},L"No Tempo");const auto noTempoBytes=noTempo.save_bytes();require(!noTempo.tempo_at(0)&&!noTempo.change_current_tempo(0,133)&&noTempo.save_bytes()==noTempoBytes&&!noTempo.dirty(),"Current Tempo does not create a missing Tempo track");
    d.load(grouped.encode());d.select_track_group(8);require(d.change_current_tempo(1536,132.25),"Current Tempo edits only selected group and track");
    require(Chunk::parse(d.save_bytes()).find("LIST","trkl")->children.front().encode()==peer.encode(),"Current Tempo preserves other group full track bytes");
    d.load(duplicate);require(d.change_current_tempo(4000,133)&&d.tempos()[1].bpm==999.99&&d.tempos()[2].bpm==133,"Current Tempo follows last effective equal-time marker without disturbing earlier peer");
}
